// Fenêtre 24 h + regroupement par similarité de titre.
// Ce nœud ne voit tous les flux QUE parce qu'un Merge les a réunis en amont :
// branché directement sur les RSS, il s'exécuterait une fois par flux et ne
// pourrait jamais compter deux sources concordantes.
const cutoff = Date.now() - 24 * 3600 * 1000;
const seen = new Map();
for (const item of $input.all()) {
  const j = item.json;
  const ts = new Date(j.isoDate || j.pubDate || Date.now()).getTime();
  if (!Number.isFinite(ts) || ts < cutoff) continue;
  const key = (j.title || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').split(' ').filter(Boolean).slice(0, 6).join(' ');
  if (!key) continue;
  if (seen.has(key)) {
    const entry = seen.get(key);
    if (!entry.sources.includes(j.link)) entry.sources.push(j.link);
    continue;
  }
  seen.set(key, {
    title: j.title,
    summary: (j.contentSnippet || '').slice(0, 600),
    link: j.link,
    sources: [j.link],
    date: new Date(ts).toISOString().slice(0, 10)
  });
}
return [...seen.values()].map((json) => ({ json }));

// FILTRE 1 — source primaire, ou deux sources secondaires concordantes.
// Appliqué en code : le prompt ne décide rien ici.
const PRIMAIRES = [
  'arxiv.org', 'europa.eu', 'eur-lex.europa.eu', 'cnil.fr', 'ssi.gouv.fr',
  'legifrance.gouv.fr', 'nature.com', 'science.org', 'insee.fr', 'ec.europa.eu',
  'anthropic.com', 'deepmind.google', 'ai.meta.com', 'mistral.ai', 'allenai.org'
];
const estPrimaire = (url) => {
  try { const h = new URL(url).hostname.replace(/^www\./, ''); return PRIMAIRES.some((d) => h === d || h.endsWith('.' + d)); }
  catch { return false; }
};

const retenus = [];
let ecartes = 0;
for (const item of $input.all()) {
  const j = item.json;
  const primaire = estPrimaire(j.link);
  if (primaire || j.sources.length >= 2) {
    retenus.push({ json: { ...j, primaire, confirmations: j.sources.length } });
  } else {
    ecartes++;
  }
}
console.log(`Filtre 1 : ${retenus.length} retenus, ${ecartes} écartés (source unique non primaire)`);
return retenus;

// Texte brut de chaque source, pour que le filtre 2 ait quelque chose à vérifier.
// Sans cette étape, « le nom propre doit exister dans la source » se contrôle
// contre un chapô RSS de 600 caractères, c'est-à-dire contre rien.
const items = $input.all();
const sortie = [];
for (let i = 0; i < items.length; i++) {
  const amont = $('Filtre 1 — concordance').all()[i];
  if (!amont) continue;
  const brut = typeof items[i].json.data === 'string' ? items[i].json.data : '';
  const texte = brut
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&[a-z]+;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (texte.length < 400) continue; // source illisible : on écarte plutôt que de deviner
  sortie.push({ json: { ...amont.json, sourceText: texte.slice(0, 12000) } });
}
console.log(`Sources exploitables : ${sortie.length} / ${items.length}`);
return sortie;

// Étape 3 du document : la sélection est un appel distinct de la rédaction.
const brut = $input.first().json.content?.[0]?.text || '';
let retenus = [];
try { retenus = JSON.parse(brut.replace(/```json|```/g, '').trim()).retenus || []; } catch { retenus = []; }
const corpus = $('Extraire le texte').all();
const sortie = retenus
  .filter((i) => Number.isInteger(i) && corpus[i])
  .slice(0, 8)
  .map((i) => ({ json: corpus[i].json }));
console.log(`Sélection : ${sortie.length} items retenus sur ${corpus.length}`);
return sortie;

// FILTRE 2 — tout nom propre cité doit apparaître dans la source.
// Vérification déterministe, pas une consigne : on relit la sortie du modèle
// contre le texte réellement récupéré. C'est ce filtre qui écarte les modèles,
// entreprises et personnes inventés.
const INITIAUX = new Set(['Le','La','Les','Un','Une','Des','Ce','Cette','Ces','Il','Elle','On','Selon','Depuis','Dans','Pour','Cependant','Ainsi','Enfin','Mais','Or','Donc','Au','Aux','Du','De','En','Par','Sur','Son','Sa','Ses','Leur','Leurs','Plus','Moins','Chaque','Tout','Toute','Aucun','Aucune']);

const amont = $('Retenir').all();
const sortie = [];
let rejets = 0;

const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const src = amont[i];
  if (!src) continue;
  const brut = items[i].json.content?.[0]?.text || '';
  let carte;
  try { carte = JSON.parse(brut.replace(/```json|```/g, '').trim()); } catch { rejets++; continue; }
  if (!carte || carte.rejet || !carte.title || !carte.body) { rejets++; continue; }

  const source = src.json.sourceText.toLowerCase();
  // On retire le premier mot de chaque phrase : en français il est capitalisé
  // sans être un nom propre.
  const noms = new Set();
  for (const phrase of carte.body.split(/(?<=[.!?])\s+/)) {
    const mots = phrase.trim().split(/\s+/).slice(1);
    for (const mot of mots) {
      const net = mot.replace(/^[^\wÀ-ÿ]+|[^\wÀ-ÿ]+$/g, '');
      if (net.length >= 3 && /^[A-ZÀ-Ý]/.test(net) && !INITIAUX.has(net)) noms.add(net);
    }
  }
  const absents = [...noms].filter((n) => !source.includes(n.toLowerCase()));
  if (absents.length) {
    console.log(`Filtre 2 — carte écartée, noms absents de la source : ${absents.join(', ')}`);
    rejets++;
    continue;
  }
  sortie.push({ json: { ...carte, link: src.json.link, sources: src.json.sources, date: src.json.date, primaire: src.json.primaire } });
}
console.log(`Filtre 2 : ${sortie.length} cartes conservées, ${rejets} écartées`);
return sortie;

// FILTRE 3 — tout chiffre doit être accompagné de l'institution qui le produit
// et de sa date. Sinon la carte est écartée : la règle du document dit de
// supprimer le chiffre, mais un corps de deux phrases amputé de son chiffre
// n'est plus la carte que le modèle a écrite.
const PORTEUR_DE_CHIFFRE = /\d[\d\s.,]*\s*(%|milliard|million|millier|€|M€|Md€|\$)|\b\d{2,}\b/i;

const sortie = [];
let rejets = 0;
for (const item of $input.all()) {
  const c = item.json;
  if (PORTEUR_DE_CHIFFRE.test(c.body)) {
    const institution = (c.institution || '').trim();
    if (!institution || !c.date) {
      console.log(`Filtre 3 — carte écartée, chiffre non attribué : ${c.title}`);
      rejets++;
      continue;
    }
  }
  if (c.title.length > 60) {
    console.log(`Filtre 3 — carte écartée, titre de ${c.title.length} caractères : ${c.title}`);
    rejets++;
    continue;
  }
  sortie.push({ json: c });
}
console.log(`Filtre 3 : ${sortie.length} cartes conservées, ${rejets} écartées`);
return sortie;

// Assemblage. L'app reçoit des briefs, pas un deck complet : le corpus statique
// et l'assemblage (ratio, alternance, répétition espacée) vivent dans
// src/lib/deckBuilder.js, où ils sont versionnés et couverts par npm run check.
// n8n ne fait que ce que lui seul peut faire — aller chercher l'actualité.
const jour = new Date().toISOString().slice(0, 10);
const briefs = $input.all().map((item, n) => {
  const c = item.json;
  const source = { name: c.institution || new URL(c.link).hostname.replace(/^www\./, ''), date: c.date };
  return {
    id: `brief-${jour}-${n}`,
    type: 'brief',
    theme: 'actualite',
    difficulty: 1,
    payload: { title: c.title, body: c.body },
    sources: [source],
    confirmations: c.sources.length,
    primaire: c.primaire
  };
});

// Persistance entre exécutions : le webhook sert ce que le cron a produit.
const store = $getWorkflowStaticData('global');
if (briefs.length >= 5) {
  store.deck = { date: jour, generatedAt: new Date().toISOString(), briefs };
}

return [{ json: { date: jour, count: briefs.length, suffisant: briefs.length >= 5, briefs } }];

// Moins de 5 briefs valides : on ne publie pas. Le deck de la veille reste en
// place dans le store, et l'app complète depuis son corpus local — la
// dégradation est silencieuse côté utilisateur, bruyante côté logs.
const j = $input.first().json;
console.warn(`ALERTE Scroll Break — ${j.count} brief(s) valide(s) le ${j.date}, publication refusée. Le deck précédent est conservé.`);
return [{ json: { alerte: true, date: j.date, count: j.count } }];

// Un nœud webhook est un déclencheur, pas une sortie : il ne peut pas recevoir
// le résultat de la branche cron. Il lit donc ce que le cron a déposé.
const store = $getWorkflowStaticData('global');
return [{ json: store.deck || { date: null, briefs: [] } }];
